        ja: '取引に含まれる通貨と、ワークスペース通貨へのレートの有無。レートがなければ額面で集計します。手動で設定できます。',
        ko: '거래의 통화와 워크스페이스 통화 환율 유무. 환율이 없으면 액면가로 집계되며, 직접 입력할 수 있습니다.',
        hi: 'आपकी प्रविष्टियों की मुद्राएं और वर्कस्पेस मुद्रा की दर है या नहीं। दर न हो तो राशि यथावत गिनी जाती है; दर हाथ से तय कर सकते हैं।',
        nl: 'Valuta’s in uw regels en of er een koers naar de werkruimtevaluta is. Zonder koers telt het bedrag nominaal; u kunt een koers instellen.',
        sv: 'Valutor i dina rader och om en kurs till arbetsytans valuta finns. Utan kurs räknas beloppet nominellt; du kan ange en kurs.',
        vi: 'Các loại tiền trong giao dịch và có tỷ giá sang tiền của không gian hay không. Không có thì tính theo mệnh giá; bạn có thể đặt tay.',
        id: 'Mata uang di entri Anda dan apakah ada kurs ke mata uang ruang kerja. Tanpa kurs jumlah dihitung apa adanya; kurs bisa diatur manual.',
        da: 'Valutaer i dine transaktioner, og om der findes en kurs til arbejdsområdets valuta. Uden kurs tælles beløbet til pålydende værdi; du kan angive en kurs manuelt.',
        nb: 'Valutaer i transaksjonene dine og om det finnes en kurs til arbeidsområdets valuta. Uten kurs telles beløpet til pålydende; du kan angi en kurs manuelt.',
        nn: 'Valutaer i transaksjonane dine og om det finst ein kurs til valutaen i arbeidsområdet. Utan kurs vert beløpet rekna til pålydande; du kan setje ein kurs manuelt.',
        fi: 'Tapahtumiesi valuutat ja onko työtilan valuuttaan kurssia. Ilman kurssia summa lasketaan nimellisarvoon; voit asettaa kurssin käsin.',
        is: 'Gjaldmiðlar í færslunum þínum og hvort gengi gagnvart gjaldmiðli vinnurýmisins sé til. Án gengis telst upphæðin á nafnvirði; þú getur stillt gengi handvirkt.',
        fo: 'Gjaldoyru í posteringunum hjá tær, og um ein kursur til gjaldoyra arbeiðsøkisins finst. Uttan kurs verður upphæddin roknað til álýddan virði; tú kanst seta ein kurs við hond.',
        cs: 'Měny ve vašich transakcích a zda existuje kurz k měně pracovního prostoru. Bez kurzu se částka počítá v nominální hodnotě; kurz můžete zadat ručně.',
        bg: 'Валутите във вашите транзакции и дали има курс към валутата на работното пространство. Без курс сумата се отчита по номинал; можете да зададете курс ръчно.',
        hr: 'Valute u vašim transakcijama i postoji li tečaj prema valuti radnog prostora. Bez tečaja iznos se računa po nominalnoj vrijednosti; tečaj možete postaviti ručno.',
        sr: 'Валуте у вашим трансакцијама и да ли постоји курс према валути радног простора. Без курса износ се рачуна по номиналној вредности; курс можете поставити ручно.',
        sl: 'Valute v vaših transakcijah in ali obstaja tečaj do valute delovnega prostora. Brez tečaja se znesek šteje po nominalni vrednosti; tečaj lahko nastavite ročno.',
        mk: 'Валутите во вашите трансакции и дали постои курс кон валутата на работниот простор. Без курс износот се смета по номинална вредност; курсот можете да го поставите рачно.',
        be: 'Валюты ў вашых транзакцыях і ці ёсць курс да валюты працоўнай прасторы. Без курсу сума лічыцца па наміналу; курс можна задаць уручную.',
        bs: 'Valute u vašim transakcijama i postoji li kurs prema valuti radnog prostora. Bez kursa iznos se računa po nominalnoj vrijednosti; kurs možete postaviti ručno.',
        hsb: 'Měny we wašich transakcijach a hač kurs k měnje dźěłoweho ruma eksistuje. Bjez kursa so suma po nominalnej hódnoće liči; kurs móžeće ručnje nastajić.',
