        vi: 'Dùng lại danh mục bạn chọn cho cùng đối tác ở các lần nhập sau. Một lần sửa không thay danh mục đã ổn định, lần thứ hai thì có.',
        id: 'Gunakan kembali kategori yang Anda pilih untuk penerima yang sama pada impor berikutnya. Satu koreksi tidak mengganti kategori yang sudah mapan; koreksi kedua mengganti.',
