            ru: 'После импорта бот находит повторяющиеся списания и просит подтвердить подписку. Выключите, если не хотите этих вопросов.',
            en: 'After an import, recurring charges are flagged and you are asked to confirm the subscription. Turn off to stop these questions.',
            kk: 'Импорттан кейін қайталанатын төлемдер табылып, жазылымды растау сұралады. Осы сұрақтар керек болмаса, өшіріңіз.',
            de: 'Nach einem Import werden wiederkehrende Abbuchungen erkannt und Sie werden gebeten, das Abo zu bestätigen. Ausschalten, um diese Fragen zu beenden.',
