            pt: 'Após uma importação, as cobranças recorrentes são detetadas e pedimos para confirmar a subscrição. Desligue para parar estas perguntas.',
            tr: 'İçe aktarmadan sonra yinelenen tahsilatlar işaretlenir ve aboneliği onaylamanız istenir. Bu soruları durdurmak için kapatın.',
            uk: 'Після імпорту повторювані списання позначаються, і вас просять підтвердити підписку. Вимкніть, щоб припинити ці запитання.',
