            pl: 'Po imporcie powtarzające się obciążenia są oznaczane i proszeni jesteście o potwierdzenie subskrypcji. Wyłącz, by nie dostawać tych pytań.',
            it: 'Dopo un import gli addebiti ricorrenti vengono segnalati e ti viene chiesto di confermare l’abbonamento. Disattiva per non ricevere più queste domande.',
            sk: 'Po importe sa opakujúce sa platby označia a budete požiadaní potvrdiť predplatné. Vypnite, ak tieto otázky nechcete.',
