            ko: '가져오기 후 반복 결제를 찾아 구독 확인을 요청합니다. 끄면 이 질문을 받지 않습니다.',
            hi: 'आयात के बाद दोहराए जाने वाले शुल्क चिह्नित होते हैं और सदस्यता की पुष्टि माँगी जाती है। ये प्रश्न बंद करने के लिए अक्षम करें।',
            nl: 'Na een import worden terugkerende afschrijvingen gemarkeerd en wordt gevraagd het abonnement te bevestigen. Zet uit om deze vragen te stoppen.',
            sv: 'Efter en import flaggas återkommande debiteringar och du ombeds bekräfta prenumerationen. Stäng av för att slippa frågorna.',
            vi: 'Sau khi nhập, các khoản trừ định kỳ được đánh dấu và bạn được hỏi xác nhận đăng ký. Tắt để không nhận các câu hỏi này.',
            id: 'Setelah impor, tagihan berulang ditandai dan Anda diminta mengonfirmasi langganan. Nonaktifkan untuk berhenti menerima pertanyaan ini.',
            da: 'Efter en import markeres tilbagevendende træk, og du bliver bedt om at bekræfte abonnementet. Slå fra for at stoppe disse spørgsmål.',
            nb: 'Etter en import blir gjentakende trekk markert, og du blir bedt om å bekrefte abonnementet. Slå av for å slutte med disse spørsmålene.',
            nn: 'Etter ein import vert gjentakande trekk markerte, og du vert beden om å stadfeste abonnementet. Slå av for å sleppe desse spørsmåla.',
            fi: 'Tuonnin jälkeen toistuvat veloitukset merkitään ja sinua pyydetään vahvistamaan tilaus. Poista käytöstä, niin kysymykset loppuvat.',
            is: 'Eftir innflutning eru endurteknar færslur merktar og þú beðinn um að staðfesta áskriftina. Slökktu til að stöðva þessar spurningar.',
            fo: 'Eftir eina innflyting verða endurtakandi gjøld merkt, og tú verður biðin um at vátta haldið. Sløkk fyri at steðga hesum spurningunum.',
            cs: 'Po importu se označí opakované platby a budete požádáni o potvrzení předplatného. Vypněte, pokud tyto dotazy nechcete.',
