        en: 'This cannot be undone. If you are the only owner of a workspace, transfer ownership first.',
        kk: 'Бұл әрекетті болдырмау мүмкін емес. Егер сіз жұмыс кеңістігінің жалғыз иесі болсаңыз, алдымен иелік құқығын беріңіз.',
